export function filterHospitalsByCriteria(
  classification: MedicalClassification | '',
  disease: string,
): KarnatakaHospital[] {
  if (disease) {
    return KARNATAKA_HOSPITALS.filter((hospital) => hospital.diseases.includes(disease));
  }
  if (classification) {
    return KARNATAKA_HOSPITALS.filter((hospital) => hospital.classifications.includes(classification));
  }
  return [...KARNATAKA_HOSPITALS];
}
